{"code":"logic_define('craft', function(a, b)
  local function norm(v)
    if type(v) ~= 'string' then return '' end
    return v:match('^%s*(.-)%s*$'):lower()
  end

  local x, y = norm(a), norm(b)

  local recipes = {
    ['wood+wood'] = 'plank',
    ['plank+plank'] = 'table',
    ['stone+wood'] = 'axe',
  }

  local key1 = x .. '+' .. y
  local key2 = y .. '+' .. x

  return recipes[key1] or recipes[key2] or 'none'
end)

report("Defined logic slot 'craft' with order-independent recipes: wood+wood=plank, plank+plank=table, wood+stone=axe; all other pairs return 'none'.")"}

